-- Shree Ji Gas Industries · MySQL 8.0
-- Import into an empty database, then run php scripts/install.php to populate starter content.

CREATE TABLE IF NOT EXISTS settings (id INT PRIMARY KEY AUTO_INCREMENT, `key` VARCHAR(100) NOT NULL UNIQUE, `value` TEXT NOT NULL, `group` VARCHAR(100) DEFAULT 'site') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS sections (id INT PRIMARY KEY AUTO_INCREMENT, section_key VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, data JSON NOT NULL, is_active INTEGER DEFAULT 1, sort_order INTEGER DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT, parent_id INTEGER DEFAULT NULL, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, icon VARCHAR(100) DEFAULT 'first-aid-kit-line', description TEXT, sort_order INTEGER DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT, cat_id INTEGER DEFAULT NULL, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, short_desc TEXT, description TEXT, specs JSON, tags TEXT, mfc_date VARCHAR(100) DEFAULT NULL, exp_date VARCHAR(100) DEFAULT NULL, keywords TEXT DEFAULT NULL, thumbnail TEXT, image_alt VARCHAR(255), gallery JSON, brochure_pdf TEXT, applications TEXT, features TEXT, is_featured INTEGER DEFAULT 0, badge_label VARCHAR(100), badge_type VARCHAR(40), status VARCHAR(30) DEFAULT 'draft', sort_order INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_categories (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, sort_order INTEGER DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_posts (id INT PRIMARY KEY AUTO_INCREMENT, cat_id INTEGER DEFAULT NULL, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, excerpt TEXT, content TEXT, thumbnail TEXT, image_alt VARCHAR(255), author VARCHAR(255), tags TEXT, is_featured INTEGER DEFAULT 0, status VARCHAR(30) DEFAULT 'draft', published_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS case_studies (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, client_name VARCHAR(255), industry VARCHAR(255), challenge TEXT, solution TEXT, results JSON, products_used JSON, thumbnail TEXT, image_alt VARCHAR(255), status VARCHAR(30) DEFAULT 'draft') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS use_cases (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, application_context TEXT, benefits TEXT, related_products JSON, thumbnail TEXT, image_alt VARCHAR(255), status VARCHAR(30) DEFAULT 'draft') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS testimonials (id INT PRIMARY KEY AUTO_INCREMENT, quote TEXT NOT NULL, client_name VARCHAR(255), organization VARCHAR(255), rating INTEGER DEFAULT 5, avatar TEXT, is_active INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS client_logos (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, logo_path TEXT, image_alt VARCHAR(255), website_url TEXT, is_active INTEGER DEFAULT 0, sort_order INTEGER DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pages (id INT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, excerpt TEXT, content TEXT, thumbnail TEXT, image_alt VARCHAR(255), status VARCHAR(30) DEFAULT 'published') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS seo_meta (id INT PRIMARY KEY AUTO_INCREMENT, page_key VARCHAR(255) NOT NULL UNIQUE, meta_title VARCHAR(255), meta_desc TEXT, focus_keyword VARCHAR(255), og_title VARCHAR(255), og_desc TEXT, og_image TEXT, canonical_url TEXT, robots VARCHAR(40) DEFAULT 'index,follow', created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS media (id INT PRIMARY KEY AUTO_INCREMENT, filename VARCHAR(255), original_name VARCHAR(255), path TEXT, image_alt VARCHAR(255), size INTEGER, type VARCHAR(100), uploaded_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_users (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(255) NOT NULL, username VARCHAR(100) UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, last_login DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS password_resets (id INT PRIMARY KEY AUTO_INCREMENT, admin_id INTEGER NOT NULL, token_hash VARCHAR(128) NOT NULL UNIQUE, otp_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, attempts INTEGER DEFAULT 0, used_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS enquiries (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(255), product VARCHAR(255), message TEXT NOT NULL, status VARCHAR(30) DEFAULT 'new', email_sent INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS rate_limits (id INT PRIMARY KEY AUTO_INCREMENT, action_key VARCHAR(255) NOT NULL UNIQUE, attempts INTEGER DEFAULT 0, window_start INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
